// Kronos Bot — sync de settings.capital_real y daily_pnl.capital_end_of_day
// (STATUS.md punto 17; revertido 2026-08-31: el crédito del bróker
// cuenta como capital real, no se excluye — decisión explícita del
// usuario, misma sesión que fijó capital_real = AccountBalance() +
// AccountCredit() el 2026-08-28. La versión anterior de este nodo
// guardaba capital_end_of_day SIN crédito (account.balance puro) para
// no mezclar unidades con capital_inicial_plan; en vez de eso ahora se
// actualizó capital_inicial_plan a la misma unidad con crédito (ver
// nota de despliegue en db/schema.sql) y se usa capital_real en ambos
// lados. Mismo patrón filesystem-v2 que el resto de nodos
// readWriteFile de este proyecto (getBinaryDataBuffer, no
// item.binary.data.data en base64).
const items = $input.all();
if (items.length === 0) return [];

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const parsed = JSON.parse(buffer.toString('utf-8'));
const account = parsed && parsed.account ? parsed.account : {};
const capitalReal = Number(account.capital_real);

if (!isFinite(capitalReal)) return [];

return [{ json: { capital_real: capitalReal } }];
